%[text] 1\.  Label Data
materials = {'UTSA-120a','SIFSIX-2-Cu-i','mmen-Mg2(dobpdc)', 'P14AQ-CNT', 'Branched PEI', 'Branched PPI' , 'Linear PEI', 'Linear PPI' , 'Piperazine', '30 wt% MEA'};

% Define classes matching the order of the materials array
classes = {'MOF', 'MOF', 'MOF', 'Polymer', 'Polymer', 'Polymer', 'Polymer', 'Polymer', 'Amine', 'Amine'};
min_energies = [31.1, 45, 71, 37, 103, 102, 75, 83, 74.4, 173];
max_energies = [31.1, 55, 71, 50, 111, 106, 77, 99, 74.4, 173];
%[text] 2\. Sort Data
[sorted_min, sort_idx] = sort(min_energies, 'ascend'); % Sorting by min_energies
sorted_max = max_energies(sort_idx);
sorted_materials = materials(sort_idx);
sorted_classes = classes(sort_idx);

% Safety check: ensure min is strictly <= max element-wise
temp_min = min(sorted_min, sorted_max);
temp_max = max(sorted_min, sorted_max);
sorted_min = temp_min;
sorted_max = temp_max;

% Apply the sorting index to the max_energies
sorted_max = max_energies(sort_idx);
sorted_materials = materials(sort_idx);

% Regenerate y_positions based on the length of the data
y_positions = 1:length(sorted_materials);

%[text] 3\. Figure Setup
figure; %[output:187173aa]
hold on; %[output:187173aa]

% Define RGB colors
c_mof = [0, 0.4470, 0.7410];      % Teal
c_poly = [0.8500, 0.3250, 0.0980]; % Rust/Orange
c_amine = [0.4940, 0.1840, 0.5560];% Purple

% Create invisible dummy plots for a clean legend
h_mof = plot(NaN, NaN, 's', 'MarkerFaceColor', c_mof, 'MarkerEdgeColor', c_mof, 'MarkerSize', 10); %[output:187173aa]
h_poly = plot(NaN, NaN, 's', 'MarkerFaceColor', c_poly, 'MarkerEdgeColor', c_poly, 'MarkerSize', 10); %[output:187173aa]
h_amine = plot(NaN, NaN, 's', 'MarkerFaceColor', c_amine, 'MarkerEdgeColor', c_amine, 'MarkerSize', 10); %[output:187173aa]
%[text] 4\. Plotting Data
% Loop through the SORTED data and draw a thick line for each range
for i = 1:length(y_positions)
    % Determine current color based on sorted class
    if strcmp(sorted_classes{i}, 'MOF')
    curr_color = c_mof;
    elseif strcmp(sorted_classes{i}, 'Polymer')
    curr_color = c_poly;
    else
    curr_color = c_amine;
    end
    if sorted_min(i) == sorted_max(i)
    % Single value (Point)
    plot(sorted_min(i), y_positions(i), 'o', 'MarkerSize', 8, ... %[output:187173aa]
        'MarkerFaceColor', curr_color, 'MarkerEdgeColor', curr_color); %[output:187173aa]
    else
    % Range (Thick line with rounded caps)
    plot([sorted_min(i), sorted_max(i)], [y_positions(i), y_positions(i)], ...
        '-', 'Color', curr_color, 'LineWidth', 9);

    % Add rounded ends
    plot(sorted_min(i), y_positions(i), 'o', 'MarkerSize', 8, ...
        'MarkerFaceColor', curr_color, 'MarkerEdgeColor', curr_color);
    plot(sorted_max(i), y_positions(i), 'o', 'MarkerSize', 8, ...
        'MarkerFaceColor', curr_color, 'MarkerEdgeColor', curr_color);
    end
end
%[text] 5\. Format Axes & Labels
yticks(y_positions); %[output:187173aa]
yticklabels(sorted_materials); %[output:187173aa]
xlabel('CO_2 Desorption Energy (kJ/mol)', 'FontSize', 12); %[output:187173aa]
grid on; %[output:187173aa]
box on; %[output:187173aa]
ylim([0.5, length(y_positions) + 0.5]); %[output:187173aa]

% Add Legend using the dummy handles
legend([h_mof, h_poly, h_amine], {'MOFs', 'Polymers / Composites', 'Liquid Amines'},'Location', 'southeast', 'FontSize', 10, 'Box', 'off',TextColor='k'); %[output:187173aa]

fig = gcf;
fig.Color = 'w'; %[output:187173aa]

ax = gca;
ax.Color = 'w'; %[output:187173aa]
ax.XColor = 'k'; %[output:187173aa]
ax.YColor = 'k'; %[output:187173aa]
ax.GridColor = [0.8 0.8 0.8]; %[output:187173aa]
ax.FontSize = 11; %[output:187173aa]

hold off; %[output:187173aa]

